def calculate_parabolic_sar(high, low, acceleration=0.02, maximum=0.2):
    sar = high.iloc[0]
    direction = 1
    for i in range(1, len(high)):
        if direction == 1:
            sar = min(sar, low.iloc[i-1])
            if high.iloc[i] > high.iloc[i-1]:
