def calculate_stochastic(close, high, low, window=14, smooth_window=3):
    %k = ((close - low.rolling(window).min()) / (high.rolling(window).max() - low.rolling(window).min())) * 100
    %d = %k.rolling(smooth_window).mean()
    return %k, %d

